#!/usr/bin/env node
/**
 * Builds data/security/bundle_archive_register.json from the artefacts that recorded bundles which no longer
 * exist.
 *
 * Two destruction events have happened. Each left behind a different kind of evidence:
 *
 *   1. The sixth/seventh reset destroyed six bundles. Their identities were captured in the audit artefact that
 *      was committed at 4f0420b, and that artefact is itself gone now — only the register built from it survives.
 *   2. The eighth reset destroyed the eight bundles created afterwards. Their audit artefact
 *      (data/security/bundle_audit.json) survived as an untracked file and was committed at 2826a67.
 *
 * The register therefore records, per bundle, WHERE the claim comes from and WHETHER that source can still be
 * inspected. A record is not evidence that a file existed; it is evidence that a file was measured. Nothing here
 * is restorable, and the generated documents must say so.
 *
 * Inputs are read-only. This script never invents a field: anything absent in the source is written as null and
 * rendered as "not recorded" downstream.
 */
"use strict";

const fs = require("node:fs");
const path = require("node:path");
const { execFileSync } = require("node:child_process");

const ROOT = path.join(__dirname, "..");
const REGISTER = path.join(ROOT, "data", "security", "bundle_archive_register.json");
const AUDIT = path.join(ROOT, "data", "security", "bundle_audit.json");

const objectExists = (sha) => {
  if (!sha) return false;
  try {
    execFileSync("git", ["cat-file", "-e", `${sha}^{commit}`], { cwd: ROOT, stdio: "ignore" });
    return true;
  } catch {
    return false;
  }
};

const normalise = (b, extra) => ({
  file: b.file,
  size: b.size === undefined ? null : b.size,
  sha256: b.sha256 || null,
  containsHead: b.containsHead || null,
  containsTree: b.containsTree || null,
  commits: b.commits === undefined ? null : b.commits,
  trackedFiles: b.trackedFiles === undefined ? null : b.trackedFiles,
  pytest: b.pytest || (b.checks && b.checks.pytest && b.checks.pytest.result) || null,
  test003: b.test003 || (b.checks && b.checks.test003 && b.checks.test003.result) || null,
  consistency: b.consistency || (b.checks && b.checks.consistency && b.checks.consistency.result) || null,
  ...extra,
});

const old = fs.existsSync(REGISTER) ? JSON.parse(fs.readFileSync(REGISTER, "utf8")) : { bundles: [] };
const audit = fs.existsSync(AUDIT) ? JSON.parse(fs.readFileSync(AUDIT, "utf8")) : { bundles: [] };

const onDisk = fs.existsSync(path.join(ROOT, "backups"))
  ? fs.readdirSync(path.join(ROOT, "backups")).filter((f) => f.endsWith(".bundle"))
  : [];
const present = new Set(onDisk);

// --- Event 1: the six bundles whose identities were recorded at 4f0420b ---------------------------------
const firstSourceCommit = old.recordedInCommit || "4f0420b74230e3220e00e957d355828c93bea49f";
const firstPresent = objectExists(firstSourceCommit);
const first = (old.bundles || []).map((b) => normalise(b, {
  destructionEvent: "reset-before-2026-11-18T03:29Z",
  evidence: {
    kind: "AUDIT_ARTEFACT_COMMITTED",
    source: `data/security/bundle_audit.json at ${firstSourceCommit.slice(0, 7)}`,
    sourceCommit: firstSourceCommit,
    sourceInspectableNow: firstPresent,
    note: firstPresent
      ? "source artefact is in this repository"
      : "source commit is absent from this repository (destroyed by a later reset); the row survives only in the register committed at 2826a67",
  },
}));

// --- Event 2: the eight bundles recorded by the surviving audit artefact --------------------------------
const secondCommit = execFileSync("git", ["log", "--format=%H", "--", "data/security/bundle_audit.json"], { cwd: ROOT, encoding: "utf8" })
  .trim().split("\n").filter(Boolean)[0] || null;
const second = (audit.bundles || []).map((b) => normalise(b, {
  destructionEvent: "reset-after-2026-11-18T04:04Z",
  evidence: {
    kind: "AUDIT_ARTEFACT_SURVIVED",
    source: `data/security/bundle_audit.json generated ${audit.generatedAt || "unknown"}`,
    sourceCommit: secondCommit,
    sourceInspectableNow: Boolean(secondCommit && objectExists(secondCommit)),
    note: `generated by \`${audit.command || "audit_bundles.js"}\`; each row was produced by cloning, fsck-ing and `
      + "testing that bundle. The measurement happened; the files are gone, so it cannot be repeated.",
  },
}));

const bundles = [...first, ...second].filter((b) => !present.has(b.file));

const register = {
  schemaVersion: 2,
  generatedAt: new Date().toISOString(),
  command: "node scripts/build_bundle_archive_register.js",
  note: "Bundles that were measured and then destroyed by workspace resets. NONE of them can be restored: the "
    + "files are gone and were never pushed. This register exists so a destroyed backup is never read as one that "
    + "was never made, and so older snapshots carrying known defects stay accounted for.",
  evidencePolicy: "Each row states where its numbers came from and whether that source can still be inspected "
    + "(`sourceInspectableNow`). A row is a record of a measurement, not a copy of a file. Rows whose source "
    + "commit is gone are UNVERIFIABLE beyond the fact that they were recorded.",
  count: bundles.length,
  bundles,
};

fs.writeFileSync(REGISTER, JSON.stringify(register, null, 2) + "\n");
console.log(`archive register: ${bundles.length} recorded destroyed bundle(s); ${onDisk.length} on disk`);
for (const b of bundles) {
  console.log(`  ${b.file.slice(-18)} ${String(b.size).padStart(9)} ${b.evidence.kind.padEnd(26)} source ${String(b.evidence.sourceCommit).slice(0, 7)} inspectable=${b.evidence.sourceInspectableNow}`);
}
